"""Frozen baseline column helper constructors for Alembic revision `0001`."""

from __future__ import annotations

import sqlalchemy as sa


def id_pk() -> sa.Column[int]:
    """Return a `BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY` column."""
    return sa.Column("id", sa.BigInteger(), sa.Identity(always=False), primary_key=True)


def bi(
    name: str,
    *,
    default: str | None = None,
    nullable: bool = False,
    pk: bool = False,
    unique: bool = False,
) -> sa.Column[int]:
    """Return a PostgreSQL `BIGINT` column (non-identity when `pk=True`)."""
    server_default = sa.text(default) if default is not None else None
    if pk:
        return sa.Column(name, sa.BigInteger(), primary_key=True, autoincrement=False)
    return sa.Column(
        name,
        sa.BigInteger(),
        nullable=nullable,
        server_default=server_default,
        unique=unique,
    )


def dbl(
    name: str,
    *,
    default: str | None = None,
    nullable: bool = False,
) -> sa.Column[float]:
    """Return a PostgreSQL `DOUBLE PRECISION` column."""
    server_default = sa.text(default) if default is not None else None
    return sa.Column(name, sa.Double(), nullable=nullable, server_default=server_default)


def txt(
    name: str,
    *,
    default: str | None = None,
    nullable: bool = False,
    pk: bool = False,
    unique: bool = False,
) -> sa.Column[str]:
    """Return a PostgreSQL `TEXT` column."""
    server_default = sa.text(default) if default is not None else None
    if pk:
        return sa.Column(name, sa.Text(), primary_key=True)
    return sa.Column(
        name,
        sa.Text(),
        nullable=nullable,
        server_default=server_default,
        unique=unique,
    )


__all__ = ["bi", "dbl", "id_pk", "txt"]
